<?php
require_once "config.php";require_once "includes/functions.php";wajibLogin();$pageTitle="Laporan";
$laporan=$pdo->query("SELECT * FROM view_laporan_transaksi ORDER BY tanggal DESC,id_transaksi DESC")->fetchAll();
$belanja=$pdo->query("SELECT * FROM view_total_belanja ORDER BY total_belanja DESC")->fetchAll();
$belum=$pdo->query("SELECT p.* FROM tbl_pelanggan p LEFT JOIN tbl_transaksi t ON p.id_pelanggan=t.id_pelanggan WHERE t.id_transaksi IS NULL ORDER BY p.nama_pelanggan")->fetchAll();
$top=$pdo->query("SELECT * FROM tbl_transaksi ORDER BY total_belanja DESC LIMIT 5")->fetchAll();
require "includes/header.php";
?>
<div class="page-intro"><div><span class="eyebrow">ANALISIS DATA TOKO</span><h2>Laporan dan Analisis</h2><p>Rekapitulasi transaksi dan pelanggan yang memanfaatkan View, JOIN, dan Subquery BAB 1–2.</p></div><button class="btn btn-outline" onclick="window.print()">▧ Cetak Laporan</button></div>
<div class="panel table-panel"><div class="panel-head"><div><h3>Laporan Transaksi</h3><p>Data dari view_laporan_transaksi</p></div><span class="count-badge"><?= count($laporan) ?> data</span></div><div class="table-scroll"><table><thead><tr><th>ID</th><th>Pelanggan</th><th>Kota</th><th>Tanggal</th><th>Total Belanja</th></tr></thead><tbody><?php foreach($laporan as $r): ?><tr><td>#<?= e($r["id_transaksi"]) ?></td><td><b><?= e($r["nama_pelanggan"]) ?></b></td><td><?= e($r["kota"]) ?></td><td><?= e($r["tanggal"]) ?></td><td><b><?= rupiah($r["total_belanja"]) ?></b></td></tr><?php endforeach; ?><?php if(!$laporan): ?><tr><td colspan="5" class="empty-state">Belum ada laporan transaksi.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="panel table-panel"><div class="panel-head"><div><h3>Total Belanja Pelanggan</h3><p>Data dari view_total_belanja</p></div></div><div class="table-scroll"><table><thead><tr><th>ID</th><th>Nama Pelanggan</th><th>Jumlah Transaksi</th><th>Total Belanja</th></tr></thead><tbody><?php foreach($belanja as $r): ?><tr><td>#<?= e($r["id_pelanggan"]) ?></td><td><b><?= e($r["nama_pelanggan"]) ?></b></td><td><?= e($r["jumlah_transaksi"]) ?></td><td><b><?= rupiah($r["total_belanja"]) ?></b></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="two-col"><div class="panel table-panel"><div class="panel-head"><div><h3>Pelanggan Belum Bertransaksi</h3><p>Analisis menggunakan LEFT JOIN</p></div></div><div class="simple-list"><?php foreach($belum as $r): ?><div class="simple-list-row"><span class="table-avatar"><?= strtoupper(substr($r["nama_pelanggan"],0,1)) ?></span><div><b><?= e($r["nama_pelanggan"]) ?></b><small><?= e($r["kota"]) ?></small></div></div><?php endforeach; ?><?php if(!$belum): ?><p class="empty-state">Semua pelanggan sudah memiliki transaksi.</p><?php endif; ?></div></div>
<div class="panel table-panel"><div class="panel-head"><div><h3>5 Transaksi Terbesar</h3><p>Urutan berdasarkan nilai belanja</p></div></div><div class="simple-list"><?php foreach($top as $i=>$r): ?><div class="simple-list-row"><span class="rank"><?= $i+1 ?></span><div><b>Transaksi #<?= e($r["id_transaksi"]) ?></b><small><?= e($r["tanggal"]) ?></small></div><strong class="list-amount"><?= rupiah($r["total_belanja"]) ?></strong></div><?php endforeach; ?><?php if(!$top): ?><p class="empty-state">Belum ada transaksi.</p><?php endif; ?></div></div></div>
